package es.upm.parque.business.model;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A ticket for one user and one date. It references the registered user it was sold to; the owner's DNI
 * is kept so the ticket remains identifiable as history after the user is deleted. Tickets generated by a
 * {@link GroupTicket} know the identifier of that group ticket. The ticket is composed of its personal passes:
 * any number of SpeedPasses and at most one Special Pass in its lifetime.
 */
public class IndividualTicket extends Ticket implements IndividualAccess {

    private static final BigDecimal SPEED_PASS_RATE = new BigDecimal("0.20");

    private final BigDecimal price;
    private final String ownerDni;
    private final String groupTicketId;
    private User owner;
    private final List<SpeedPass> speedPasses = new ArrayList<>();
    private SpecialPass specialPass;

    public IndividualTicket(String id, LocalDate date, BigDecimal price, User owner) {
        this(id, date, price, owner.getDni(), owner, null);
    }

    /** Restores a ticket, possibly generated by a group ticket or whose owner no longer exists. */
    public IndividualTicket(String id, LocalDate date, BigDecimal price, String ownerDni, User owner,
            String groupTicketId) {
        super(id, date);
        this.price = price;
        this.ownerDni = ownerDni;
        this.owner = owner;
        this.groupTicketId = groupTicketId;
    }

    @Override
    public BigDecimal getPrice() {
        return price;
    }

    public String getOwnerDni() {
        return ownerDni;
    }

    /** @return the registered owner, or null if that user no longer exists */
    public User getOwner() {
        return owner;
    }

    /** @return the identifier of the group ticket that generated this ticket, or null for a standalone ticket */
    public String getGroupTicketId() {
        return groupTicketId;
    }

    @Override
    public List<User> getAdmittedUsers() {
        return owner == null ? List.of() : List.of(owner);
    }

    public boolean isOwnedBy(User user) {
        return owner == user;
    }

    public List<SpeedPass> getSpeedPasses() {
        return Collections.unmodifiableList(speedPasses);
    }

    /** @return the Special Pass bought for this ticket (in any status), or null if none was bought */
    @Override
    public SpecialPass getSpecialPass() {
        return specialPass;
    }

    /** @return every pass of this ticket, SpeedPasses first */
    public List<Pass> getPasses() {
        List<Pass> passes = new ArrayList<>(speedPasses);
        if (specialPass != null) {
            passes.add(specialPass);
        }
        return passes;
    }

    @Override
    public List<IndividualAccess> getIndividualAccesses() {
        return List.of(this);
    }

    @Override
    public SpeedPass findAvailableSpeedPass() {
        for (SpeedPass pass : speedPasses) {
            if (pass.isAvailable()) {
                return pass;
            }
        }
        return null;
    }

    /** Price of one SpeedPass: 20% of the price stored in this ticket. */
    public BigDecimal getSpeedPassPrice() {
        return price.multiply(SPEED_PASS_RATE).setScale(2, RoundingMode.HALF_UP);
    }

    /** Creates {@code quantity} new SpeedPasses, numbered after the existing ones. */
    public List<SpeedPass> addSpeedPasses(int quantity) {
        List<SpeedPass> created = new ArrayList<>();
        for (int i = 0; i < quantity; i++) {
            SpeedPass pass = new SpeedPass(getId() + "-S" + (speedPasses.size() + 1), getSpeedPassPrice(),
                PassStatus.AVAILABLE);
            speedPasses.add(pass);
            created.add(pass);
        }
        return created;
    }

    /**
     * Creates the Special Pass of this ticket.
     *
     * @throws IllegalArgumentException if a Special Pass was already bought, whatever its status
     */
    public SpecialPass addSpecialPass() {
        if (specialPass != null) {
            throw new IllegalArgumentException("Ticket " + getId() + " already had a Special Pass");
        }
        specialPass = new SpecialPass(getId() + "-SPECIAL", getPrice().setScale(2, RoundingMode.HALF_UP),
            PassStatus.AVAILABLE);
        return specialPass;
    }

    /**
     * Deletes every pass of this ticket (SpeedPasses, then the Special Pass), used when the ticket is deleted.
     *
     * @return the removed passes, so the deletion can be undone with {@link #restorePass}
     */
    public List<Pass> removePasses() {
        List<Pass> removed = getPasses();
        speedPasses.clear();
        specialPass = null;
        return removed;
    }

    /** Re-attaches a stored pass when the ticket is restored. */
    public void restorePass(Pass pass) {
        if (pass instanceof SpeedPass speed) {
            speedPasses.add(speed);
        } else if (pass instanceof SpecialPass special) {
            specialPass = special;
        }
    }

    /** Called when the owner is deleted; the ticket stays as a historical record. */
    public void detachOwner() {
        owner = null;
    }
}
